package com.nthexperience.desktop;

import android.content.Context;
import android.os.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.*;
import java.util.concurrent.*;

/** Virtual recovery folder over the verified bin, not a raw directory of internal payloads. */
final class RecyclePanel extends VistaShell {
    private final ExecutorService worker=Executors.newSingleThreadExecutor();private final Handler main=new Handler(Looper.getMainLooper());private final Runnable changed;private final DocumentOps.Cancel cancel=new DocumentOps.Cancel();
    private List<JSONObject> items=new ArrayList<>();private String selected="",sort="Date deleted";private boolean closed,busy,loaded,descending=true;
    RecyclePanel(Context context,DesktopStore store,Actions actions,Runnable changed){super(context,store,actions,"Search Recycle Bin");this.changed=changed;commands.addView(command("Restore this item",this::restoreSelected),new LayoutParams(-2,dp(38)));commands.addView(command("Empty Recycle Bin…",this::confirmEmpty),new LayoutParams(-2,dp(38)));commands.addView(command("Properties",this::properties),new LayoutParams(-2,dp(38)));explorerChrome(this::menu);enableNavigationToggle();start("recycle");refresh();}
    @Override void render(){if(closed)return;side.removeAllViews();sideLink("Computer",()->actions.open("@computer"));sideLink("Restore all items",this::restoreAll);sideLink("Empty Recycle Bin…",this::confirmEmpty);sideLink("Recycle Bin Properties",this::properties);address.setText("Recycle Bin");up.setEnabled(true);LinearLayout column=column();
        if(busy)column.addView(Aero.text(getContext(),"Working… Recovery copies are kept until restoration is verified.",12,Aero.INK));
        LinearLayout header=new LinearLayout(getContext());String[] names={"Name","Original location","Date deleted","Size"};float[] weights={.35f,.27f,.24f,.14f};for(int i=0;i<names.length;i++){String name=names[i];TextView label=command(name,()->{descending=sort.equals(name)&&!descending;sort=name;render();});label.setTextSize(10);label.setSingleLine();label.setEllipsize(android.text.TextUtils.TruncateAt.END);label.setPadding(dp(3),0,dp(2),0);label.setContentDescription("Sort Recycle Bin by "+name);header.addView(label,new LayoutParams(0,dp(32),weights[i]));}column.addView(header);
        List<JSONObject> shown=new ArrayList<>();for(JSONObject item:items)if(query().isEmpty()||item.optString("name").toLowerCase(Locale.ROOT).contains(query()))shown.add(item);shown.sort((a,b)->{int result=sort.equals("Size")?Long.compare(a.optLong("size"),b.optLong("size")):sort.equals("Date deleted")?Long.compare(a.optLong("date"),b.optLong("date")):(sort.equals("Original location")?a.optString("location"):a.optString("name")).compareToIgnoreCase(sort.equals("Original location")?b.optString("location"):b.optString("name"));return descending?-result:result;});
        for(JSONObject item:shown){LinearLayout row=new LinearLayout(getContext());row.setMinimumHeight(dp(48));row.setGravity(Gravity.CENTER_VERTICAL);row.setFocusable(true);row.setContentDescription("Recycle item: "+item.optString("name"));if(item.optString("id").equals(selected))row.setBackground(Aero.panel(getContext(),0xffe4f3ff,0xffc8e3f5,1,0xff89b3cf));String[] values={item.optString("name"),item.optString("location","Original folder"),java.text.DateFormat.getDateTimeInstance(java.text.DateFormat.SHORT,java.text.DateFormat.SHORT).format(new Date(item.optLong("date"))),android.text.format.Formatter.formatShortFileSize(getContext(),item.optLong("size"))};for(int i=0;i<values.length;i++){TextView cell=Aero.text(getContext(),values[i],11,Aero.INK);cell.setMaxLines(2);cell.setEllipsize(android.text.TextUtils.TruncateAt.END);cell.setPadding(dp(3),dp(4),dp(2),dp(4));row.addView(cell,new LayoutParams(0,-2,weights[i]));}row.setOnClickListener(v->{selected=item.optString("id");render();});ContextMenus.bind(row,(x,y)->{selected=item.optString("id");DesktopContextMenu menu=new DesktopContextMenu(getContext(),"Recycle item commands");menu.item("Restore","recycle",!busy,this::restoreSelected);menu.item("Delete permanently…","delete",!busy,()->confirmRemove(item));menu.item("Properties","control",()->itemProperties(item));ContextMenus.show(menu,row,x,y);});column.addView(row);}
        if(shown.isEmpty())column.addView(Aero.text(getContext(),loaded?query().isEmpty()?"Recycle Bin is empty":"No matching recovery files":"Loading Recycle Bin…",15,Aero.INK));status.setText(items.size()+" item"+(items.size()==1?"":"s")+" • "+android.text.format.Formatter.formatShortFileSize(getContext(),items.stream().mapToLong(i->i.optLong("size")).sum())+" / "+store.prefs.getInt("recycle_capacity_mb",250)+" MB"+(busy?" • Working…":""));body(scrolling(column));
    }
    private JSONObject selected(){for(JSONObject item:items)if(item.optString("id").equals(selected))return item;return null;}
    private void restoreSelected(){JSONObject item=selected();if(item==null){Toast.makeText(getContext(),"Select a recovery file first.",Toast.LENGTH_SHORT).show();return;}operation(()->{RecycleBin.restore(getContext(),item,cancel);return "File restored";});}
    private void restoreAll(){if(items.isEmpty()||busy)return;List<JSONObject> snapshot=new ArrayList<>(items);operation(()->{int done=0;for(JSONObject item:snapshot){RecycleBin.restore(getContext(),item,cancel);done++;}return done+" files restored";});}
    private void confirmRemove(JSONObject item){Aero.dialog(getContext()).setTitle("Delete recovery copy?").setMessage(item.optString("name")+". This cannot be undone.").setPositiveButton("Delete",(d,w)->operation(()->{RecycleBin.remove(getContext(),item);return "Recovery copy removed";})).setNegativeButton("Cancel",null).show();}
    private void confirmEmpty(){if(busy)return;Aero.dialog(getContext()).setTitle("Empty Recycle Bin?").setMessage("Permanently remove all recovery copies? This cannot be undone.").setPositiveButton("Empty",(d,w)->operation(()->{RecycleBin.empty(getContext());return "Recycle Bin emptied";})).setNegativeButton("Cancel",null).show();}
    private void itemProperties(JSONObject item){Aero.dialog(getContext()).setTitle(item.optString("name")).setMessage("Original location: "+item.optString("location","Original folder")+"\nDeleted: "+java.text.DateFormat.getDateTimeInstance().format(new Date(item.optLong("date")))+"\nSize: "+android.text.format.Formatter.formatFileSize(getContext(),item.optLong("size"))+"\n"+(item.optBoolean("deleted")?"Original deletion confirmed":"Recovery copy; original deletion unconfirmed")+"\nRestore keeps both names if the destination already exists.").setPositiveButton("OK",null).show();}
    private void properties(){LinearLayout body=column();body.addView(Aero.text(getContext(),"Maximum bin size (new deletions)",14,Aero.INK));Spinner capacity=new Spinner(getContext());String[] choices={"100 MB","250 MB","500 MB","1 GB","2 GB"};int[] values={100,250,500,1024,2048};capacity.setAdapter(new ArrayAdapter<>(getContext(),android.R.layout.simple_spinner_dropdown_item,choices));int current=store.prefs.getInt("recycle_capacity_mb",250);for(int i=0;i<values.length;i++)if(values[i]==current)capacity.setSelection(i);capacity.setContentDescription("Recycle Bin maximum size");body.addView(capacity);CheckBox icon=Aero.check(getContext(),"Show Recycle Bin on desktop",store.pinned("@recycle"));body.addView(icon);body.addView(Aero.text(getContext(),"Regular files up to 100 MB each; up to 200 recovery files. Existing copies are kept when the limit is lowered. Folders and unsupported locations require explicit permanent-deletion confirmation. Files deleted in other apps are not collected.",12,Aero.INK));Aero.dialog(getContext()).setTitle("Recycle Bin Properties").setView(body).setPositiveButton("Apply",(d,w)->{store.prefs.edit().putInt("recycle_capacity_mb",values[capacity.getSelectedItemPosition()]).apply();if(icon.isChecked()!=store.pinned("@recycle"))store.toggle("@recycle");changed.run();render();}).setNegativeButton("Cancel",null).show();}
    private void menu(String label){DesktopContextMenu menu=new DesktopContextMenu(getContext(),"Recycle Bin "+label+" menu");if(label.equals("View")){for(String name:new String[]{"Name","Original location","Date deleted","Size"})menu.checked("Sort by "+name,sort.equals(name),()->{sort=name;render();});menu.item("Refresh","refresh",this::refresh);}else{menu.item("Restore this item","recycle",selected()!=null&&!busy,this::restoreSelected);menu.item("Restore all items","recycle",!items.isEmpty()&&!busy,this::restoreAll);menu.item("Empty Recycle Bin…","delete",!busy,this::confirmEmpty);menu.item("Properties","control",this::properties);}ContextMenus.centered(commands,(x,y)->ContextMenus.show(menu,commands,x,y));}
    interface Job<T>{T run()throws Exception;}
    private <T> void run(Job<T> job,java.util.function.Consumer<T> done){if(busy||closed)return;busy=true;worker.execute(()->{try{T result=job.run();main.post(()->{busy=false;if(!closed)done.accept(result);});}catch(Exception ex){main.post(()->{busy=false;if(!closed){Toast.makeText(getContext(),ex.getMessage()==null?"Operation unavailable":ex.getMessage(),Toast.LENGTH_LONG).show();DesktopSounds.play(getContext(),"error");loaded=true;render();}});}});}
    private void operation(Job<String> job){run(job,text->{Toast.makeText(getContext(),text,Toast.LENGTH_LONG).show();DesktopSounds.play(getContext(),"complete");changed.run();refresh();});}
    void refresh(){run(()->RecycleBin.list(getContext()),values->{items=values;loaded=true;render();});}
    @Override JSONObject extraState(){JSONObject value=new JSONObject();GadgetLayout.put(value,"sort",sort);GadgetLayout.put(value,"descending",descending);GadgetLayout.put(value,"selected",selected);return value;}
    @Override void restoreExtra(JSONObject state){if(state!=null){sort=state.optString("sort","Date deleted");descending=state.optBoolean("descending",true);selected=state.optString("selected");}}
    @Override void showFolders(){toggleNavigationPane();}
    @Override void goUp(){actions.open("@computer");}
    @Override void close(){if(closed)return;closed=true;cancel.cancel();worker.shutdown();main.removeCallbacksAndMessages(null);}
}
